#!/usr/bin/env node
// Copies the instrument format (shared/instruments/schema.json) and the seed
// instruments (shared/instruments/library/*.json) into the generate-instrument
// Edge Function, which can't read files outside supabase/functions at runtime.
//
//   node scripts/instrument-ai/sync-assets.mjs          # rewrite the generated file
//   node scripts/instrument-ai/sync-assets.mjs --check  # exit 1 if it is stale
//
// The generator reads whatever schema and seeds exist, so a new format version
// or new library files only need this script re-run (the Node tests check it).
import { readFileSync, readdirSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const instruments = join(root, "shared", "instruments");
const out = join(root, "supabase", "functions", "_shared", "instrument-ai", "assets.generated.ts");

export function render() {
  const schema = JSON.parse(readFileSync(join(instruments, "schema.json"), "utf8"));
  const seeds = readdirSync(join(instruments, "library"))
    .filter((name) => name.endsWith(".json"))
    .sort()
    .map((name) => JSON.parse(readFileSync(join(instruments, "library", name), "utf8")));
  return [
    "// GENERATED by scripts/instrument-ai/sync-assets.mjs from shared/instruments/. Do not edit.",
    "// deno-lint-ignore-file",
    `export const INSTRUMENT_SCHEMA: Record<string, unknown> = ${JSON.stringify(schema, null, 2)};`,
    "",
    `export const SEED_INSTRUMENTS: Record<string, unknown>[] = ${JSON.stringify(seeds, null, 2)};`,
    "",
  ].join("\n");
}

if (import.meta.url === `file://${process.argv[1]}`) {
  const next = render();
  let current = "";
  try { current = readFileSync(out, "utf8"); } catch { /* first run */ }
  if (process.argv.includes("--check")) {
    if (current !== next) {
      console.error("assets.generated.ts is stale: run node scripts/instrument-ai/sync-assets.mjs");
      process.exit(1);
    }
    console.log("instrument generator assets are up to date");
  } else if (current !== next) {
    writeFileSync(out, next);
    console.log(`wrote ${out}`);
  }
}
